function anagramCheck(str1, str2) {
  // Remove whitespace, convert strings to lowercase, and split into arrays
  let arr1 = str1.replace(/\s/g, '').toLowerCase().split('');
  let arr2 = str2.replace(/\s/g, '').toLowerCase().split('');

  // If the arrays are different lengths, they cannot be anagrams
  if (arr1.length !== arr2.length) {
    return false;
  }

  // Sort both arrays, and check if they are the same
  let sortedArr1 = arr1.sort();
  let sortedArr2 = arr2.sort();

  for (let i=0; i<sortedArr1.length; i++) {
    if (sortedArr1[i] !== sortedArr2[i]) {
      return false;
    }
  }
  return true;
}

public class BinaryTree { 

    // Root of Binary Tree 
    Node root; 

    // Function to print binary tree in level order 
    void printLevelOrder() { 
        int h = height(root); 
        int i; 
        for (i = 1; i <= h; i++) 
            levelOrder(root, i); 
    } 

    // Print nodes at a given level 
    void levelOrder(Node root, int level) { 
        if (root == null) 
            return; 
        if (level == 1) 
            System.out.print(root.data + " "); 
        else if (level > 1) { 
            levelOrder(root.left, level - 1); 
            levelOrder(root.right, level - 1); 
        } 
    } 

    // Compute the height of a tree--the number of nodes 
    // along the longest path from the root node down to 
    // the farthest leaf node 
    int height(Node root) { 
        if (root == null) 
            return 0; 
        else { 
            // compute height of each subtree 
            int lheight = height(root.left); 
            int rheight = height(root.right); 

            // use the larger one 
            if (lheight > rheight) 
                return (lheight + 1); 
            else
                return (rheight + 1); 
        } 
    } 
}

