"""
Create a class named 'Stack' with the following methods: push, pop, peek, isEmpty.
"""

class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def peek(self):
        return self.items[-1]

    def isEmpty(self):
        return self.items == []

"""
Use a Linked List structure to implement a stack data structure.
"""

class Node:
    def __init__(self, val):
        self.value = val
        self.next = None

class Stack:
    def __init__(self):
        self.top = None
        self.size = 0

    def push(self, val):
        new_node = Node(val)
        new_node.next = self.top
        self.top = new_node
        self.size += 1

    def pop(self):
        if self.top == None:
            return None
        else:
            pop_node = self.top
            self.top = self.top.next
            self.size -= 1
            return pop_node.value

