class Queue:
    def __init__(self):
        self.queue = []

    def enqueue(self, val):
        self.queue.append(val)

    def dequeue(self):
        if self.queue:
            return self.queue.pop(0)
        else:
            return None

    def peek(self):
        if self.queue:
            return self.queue[0]
        else:
            return None

