                difference = arr[j] - arr[i]
    return difference

def secondLargest(arr):
    first = 0
    second = 0
    for i in range(len(arr)):
        if arr[i] > first:
            second, first = first, arr[i]
        elif (arr[i] > second and arr[i] < first):
            second = arr[i]
    return second

